SELECT 
FROM biz_guide_sheet s
LEFT JOIN sys_user u ON u.user_id = s.creator_id



            s.del_flag = #{delFlag}


            s.del_flag = '0'



        AND s.sheet_title LIKE CONCAT('%', #{sheetTitle}, '%')

    AND s.grade = #{grade}
    AND s.semester = #{semester}
    AND s.lesson_num = #{lessonNum}
    AND s.is_public = #{isPublic}
    AND s.creator_id = #{creatorId}




            AND (
                s.creator_id = #{params.viewerId}
                OR (s.is_public = 'Y'
                    AND s.county_dept_id = #{params.countyDeptId}
                    AND s.del_flag = '0')
            )


            AND 1 = 0




        AND s.creator_id = #{params.viewerId}
        AND s.is_public = 'N'


        AND s.is_public = 'Y'
        AND s.county_dept_id = #{params.countyDeptId}
        AND s.del_flag = '0'


ORDER BY COALESCE(s.update_time, s.create_time) DESC, s.sheet_id DESC

